CREATE DATABASE IF NOT EXISTS class_db;
USE class_db;

DROP TABLE IF EXISTS demographics;

CREATE TABLE demographics (
   state      VARCHAR(2) NOT NULL PRIMARY KEY,
   population INTEGER    NOT NULL
);

USE class_db;

DROP TABLE IF EXISTS `statistics`;

CREATE TABLE `statistics` (
   `date`        VARCHAR(19) NOT NULL,
   state         VARCHAR(2)  NOT NULL,
   total_cases   INTEGER     NOT NULL,
   total_deaths  INTEGER     NOT NULL
);


-- Question 1
SELECT
    `date`,
    state,
    total_cases,
    total_cases - LAG(total_cases) OVER (
        PARTITION BY state
        ORDER BY `date`
    ) AS new_cases
FROM `statistics`
ORDER BY state, `date`;

-- Question 2
SELECT `date`, state, new_cases,
       AVG(new_cases) OVER (PARTITION BY state ORDER BY `date`
                            ROWS BETWEEN 2 PRECEDING AND 2 FOLLOWING) AS smoothed
FROM (
    SELECT `date`, state,
           total_cases - LAG(total_cases) OVER (PARTITION BY state ORDER BY `date`) AS new_cases
    FROM `statistics`
) AS daily;

-- Question 3
SELECT `date`, state, total_cases, total_deaths
FROM (
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY state ORDER BY `date` DESC) AS rn
    FROM `statistics`
) AS ranked
WHERE rn = 1;

-- Question 4
SELECT l.state, l.total_deaths / d.population * 100000 AS deaths_per_100k
FROM (
    SELECT state, total_deaths,
           ROW_NUMBER() OVER (PARTITION BY state ORDER BY `date` DESC) AS rn
    FROM `statistics`
) AS l
JOIN demographics AS d ON l.state = d.state
WHERE rn = 1;

-- Question 5
WITH daily AS (
    SELECT `date`, state,
           total_deaths - LAG(total_deaths) OVER (PARTITION BY state ORDER BY `date`) AS new_deaths
    FROM `statistics`
),
ranked AS (
    SELECT *, RANK() OVER (PARTITION BY state ORDER BY new_deaths DESC) AS rnk
    FROM daily
)
SELECT `date`, state, new_deaths
FROM ranked
WHERE rnk = 1
ORDER BY `date` DESC, new_deaths DESC;